'use strict';

// MODULES //

var isUndefinedOrNull = require( '@stdlib/assert/is-undefined-or-null' );
var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var accessors = require( './accessors.js' );


// FUNCTIONS //

/**
* Returns the string representation of an array element.
*
* @private
* @param {Collection} x - input array
* @param {integer} idx - element index
* @returns {string} string representation
*/
function str( x, idx ) {
	var v = x[ idx ];
	if ( isUndefinedOrNull( v ) ) {
		return '';
	}
	return String( v );
}


// MAIN //

/**
* Returns a string created by joining strided array elements using a conjunction and alternative indexing semantics.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {string} prefix - string to prepend
* @param {string} suffix - string to append
* @param {string} conjunction - conjunction before the last element
* @param {boolean} oxfordComma - boolean specifying whether to include an Oxford comma
* @param {Collection} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {string} joined string
*
* @example
* var x = [ 1, 2, 3, 4 ];
*
* var out = gconjoin( x.length, '', '', 'and', true, x, 1, 0 );
* // returns '1, 2, 3, and 4'
*/
function gconjoin( N, prefix, suffix, conjunction, oxfordComma, x, strideX, offsetX ) { // eslint-disable-line max-len
	var out;
	var ix;
	var o;
	var i;

	if ( N <= 0 ) {
		return '';
	}
	o = arraylike2object( x );
	if ( o.accessorProtocol ) {
		return accessors( N, prefix, suffix, conjunction, oxfordComma, o, strideX, offsetX ); // eslint-disable-line max-len
	}

	// First element...
	ix = offsetX;
	out = prefix + str( x, ix );
	ix += strideX;

	// Middle elements...
	for ( i = 1; i < N - 1; i++ ) {
		out += ', ' + str( x, ix );
		ix += strideX;
	}

	// Last element (when N >= 2)...
	if ( N >= 2 ) {
		if ( conjunction === '' ) {
			out += ', ' + str( x, ix );
		} else if ( N >= 3 && oxfordComma ) {
			out += ', ' + conjunction + ' ' + str( x, ix );
		} else {
			out += ' ' + conjunction + ' ' + str( x, ix );
		}
	}
	return out + suffix;
}


// EXPORTS //

module.exports = gconjoin;
